#include "ChronicleStore.hpp"
namespace elysium::history {bool ChronicleStore::append(ChronicleEvent e,std::string&w){if(!e.id||!e.type||!e.version){w="invalid chronicle event";return false;}if(byId_.count(e.id)){w="immutable duplicate";return false;}if(!events_.empty()&&e.epoch<events_.back().epoch){w="non-append epoch";return false;}byId_[e.id]=events_.size();events_.push_back(std::move(e));return true;}std::vector<ChronicleEvent>ChronicleStore::byEntity(StableId id)const{std::vector<ChronicleEvent>v;for(auto&e:events_){auto has=[&](auto&xs){return std::find(xs.begin(),xs.end(),id)!=xs.end();};if(has(e.participants)||has(e.sites)||has(e.items)||has(e.factions))v.push_back(e);}return v;}std::vector<ChronicleEvent>ChronicleStore::visibleTimeline()const{std::vector<ChronicleEvent>v;for(auto&e:events_)if(e.visible)v.push_back(e);return v;}std::size_t ChronicleStore::compactLowSignificance(std::uint8_t b){std::size_t n=0;for(auto&e:events_)if(e.significance<b&&!e.supersedes){e.payload=0;++n;}return n;}}
